{"version":3,"file":"document-title-BmOJ4tzL.js","sources":["../../../utils/document-title.js"],"sourcesContent":["import {isServer} from 'lit';

/**
 * Sets the browser tab title (WCAG 2.4.2 — pages must have a descriptive title).
 * No-op during SSR; the client hydration pass applies it.
 * @param {string} title
 */
export function setDocumentTitle(title) {
 if (isServer) return;
 document.title = title ? `${title} · WDF Lab` : 'WDF Lab';
}
"],"names":["setDocumentTitle","title","isServer","document"],"mappings":"+BAOO,SAASA,EAAiBC,CAAK,EAChCC,GACJC,CAAAA,SAASF,KAAK,CAAGA,EAAQ,GAAGA,EAAM,aAAU,CAAC,CAAG,SAAA,CAClD"}
